// 두벌식 ↔ QWERTY 자판 전환 (한/영 오타 복원)
//
// "한영키를 안 누르고 `gksrmf` 쳐놓고 `한글`을 찾는" 입력을 되돌린다.
// 순수함수 — 코퍼스도, 튜닝 상수도, 임계값도 없다. 입력만으로 출력이 완전히 결정된다.
//
// **이 모듈은 매칭에 관여하지 않는다.** fuzzly의 검색은 이 함수를 호출하지 않으며,
// `swapLayout`을 언제 적용할지·결과를 어떻게 보여줄지는 소비자의 제품 결정이다
// (두 해석을 하나의 순위로 합치려면 코퍼스마다 다른 점수 상수가 필요해지는데,
//  그건 라이브러리가 가질 수 없는 지식이다 — design_notes.md Case 2 참고).
//
// 전제: 두벌식 + QWERTY. 세벌식·Dvorak·Colemak은 대상이 아니다.

/** QWERTY 키 → 두벌식 자모. shift가 다른 자모를 내는 건 q w e r t o p 7개뿐이다. */
const KEY_TO_JAMO: Record<string, string> = {
    q: "ㅂ",
    w: "ㅈ",
    e: "ㄷ",
    r: "ㄱ",
    t: "ㅅ",
    y: "ㅛ",
    u: "ㅕ",
    i: "ㅑ",
    o: "ㅐ",
    p: "ㅔ",
    a: "ㅁ",
    s: "ㄴ",
    d: "ㅇ",
    f: "ㄹ",
    g: "ㅎ",
    h: "ㅗ",
    j: "ㅓ",
    k: "ㅏ",
    l: "ㅣ",
    z: "ㅋ",
    x: "ㅌ",
    c: "ㅊ",
    v: "ㅍ",
    b: "ㅠ",
    n: "ㅜ",
    m: "ㅡ",
    Q: "ㅃ",
    W: "ㅉ",
    E: "ㄸ",
    R: "ㄲ",
    T: "ㅆ",
    O: "ㅒ",
    P: "ㅖ",
};

/** 자모 → QWERTY 키. KEY_TO_JAMO의 역. 대문자 키는 shift 조합을 뜻한다. */
const JAMO_TO_KEY: Record<string, string> = {};
for (const key of Object.keys(KEY_TO_JAMO)) {
    JAMO_TO_KEY[KEY_TO_JAMO[key]] = key;
}

/** shift를 눌러야 **다른 자모**가 나오는 키 (소문자 기준). CapsLock 추론의 근거가 된다. */
const SHIFTABLE_KEYS = new Set("qwertop");

const LEADS = "ㄱㄲㄴㄷㄸㄹㅁㅂㅃㅅㅆㅇㅈㅉㅊㅋㅌㅍㅎ";
const MEDIALS = "ㅏㅐㅑㅒㅓㅔㅕㅖㅗㅘㅙㅚㅛㅜㅝㅞㅟㅠㅡㅢㅣ";
/** 종성. 인덱스 0 = 받침 없음. */
const FINALS = "\u0000ㄱㄲㄳㄴㄵㄶㄷㄹㄺㄻㄼㄽㄾㄿㅀㅁㅂㅄㅅㅆㅇㅈㅊㅋㅌㅍㅎ";

const SYLLABLE_BASE = 0xac00;
const SYLLABLE_LAST = 0xd7a3;
const MEDIAL_COUNT = 21;
const FINAL_COUNT = 28;

/** 두 모음이 이어질 때 합쳐지는 겹모음 (ㅗ+ㅏ=ㅘ 등). */
const MEDIAL_JOIN: Record<string, string> = {
    ㅗㅏ: "ㅘ",
    ㅗㅐ: "ㅙ",
    ㅗㅣ: "ㅚ",
    ㅜㅓ: "ㅝ",
    ㅜㅔ: "ㅞ",
    ㅜㅣ: "ㅟ",
    ㅡㅣ: "ㅢ",
};

/** 받침에 자음이 덧붙을 때 합쳐지는 겹받침 (ㄱ+ㅅ=ㄳ 등). */
const FINAL_JOIN: Record<string, string> = {
    ㄱㅅ: "ㄳ",
    ㄴㅈ: "ㄵ",
    ㄴㅎ: "ㄶ",
    ㄹㄱ: "ㄺ",
    ㄹㅁ: "ㄻ",
    ㄹㅂ: "ㄼ",
    ㄹㅅ: "ㄽ",
    ㄹㅌ: "ㄾ",
    ㄹㅍ: "ㄿ",
    ㄹㅎ: "ㅀ",
    ㅂㅅ: "ㅄ",
};

/** 겹모음/겹받침 → 구성 자모 2개. 역방향(한→영)에서 키 2번으로 풀어내는 데 쓴다. */
const CLUSTER_SPLIT: Record<string, string> = {};
for (const pair of Object.keys(MEDIAL_JOIN)) {
    CLUSTER_SPLIT[MEDIAL_JOIN[pair]] = pair;
}
for (const pair of Object.keys(FINAL_JOIN)) {
    CLUSTER_SPLIT[FINAL_JOIN[pair]] = pair;
}

const isMedial = (jamo: string): boolean => MEDIALS.includes(jamo);
const isFinal = (jamo: string): boolean => FINALS.indexOf(jamo) > 0;

/**
 * 자모 스트림을 두벌식 IME와 동일하게 조합한다.
 *
 * 출력은 실제 IME journey와 같은 형태다 (`ㅎ → 하 → 한 → 한ㄱ → 한글`). 조합이 안 되는
 * 자모는 그대로 흘려보내므로, 한국어가 아닌 입력은 고아 자모가 잔뜩 남는다 — 그 자체가
 * "이 해석은 틀렸다"는 신호로 읽힌다.
 */
function composeJamos(jamos: string[]): string {
    let out = "";
    let lead: string | null = null;
    let medial: string | null = null;
    let final: string | null = null;

    const flush = (): void => {
        if (lead !== null && medial !== null) {
            const code =
                SYLLABLE_BASE +
                (LEADS.indexOf(lead) * MEDIAL_COUNT + MEDIALS.indexOf(medial)) * FINAL_COUNT +
                (final === null ? 0 : FINALS.indexOf(final));
            out += String.fromCharCode(code);
        } else {
            if (lead !== null) out += lead;
            if (medial !== null) out += medial;
            if (final !== null) out += final;
        }
        lead = medial = final = null;
    };

    for (const jamo of jamos) {
        if (isMedial(jamo)) {
            if (final !== null) {
                // 도깨비불: 받침이 다음 음절의 초성으로 넘어간다 (한 + ㅏ → 하나).
                const split: string | undefined = CLUSTER_SPLIT[final];
                const carried = split ? split[1] : final;
                final = split ? split[0] : null;
                flush();
                lead = carried;
                medial = jamo;
            } else if (medial !== null && MEDIAL_JOIN[medial + jamo]) {
                medial = MEDIAL_JOIN[medial + jamo];
            } else if (medial !== null) {
                flush();
                medial = jamo;
            } else {
                // 초성이 없어도 버퍼에 담아둔다 — 뒤따르는 모음과 겹모음을 이룰 수 있다 (ㅗ+ㅏ → ㅘ)
                medial = jamo;
            }
        } else if (lead !== null && medial !== null && final === null && isFinal(jamo)) {
            final = jamo;
        } else if (final !== null && FINAL_JOIN[final + jamo]) {
            final = FINAL_JOIN[final + jamo];
        } else {
            flush();
            lead = jamo;
        }
    }
    flush();
    return out;
}

/**
 * conjoining jamo(U+1100-U+11C2, NFD 분해형) → 호환 자모.
 *
 * 세 블록이 각각 LEADS/MEDIALS/FINALS와 **같은 순서**라 인덱스 산술로 끝난다.
 * macOS 파일명 등 NFD로 정규화된 한글이 그대로 통과해버리지 않게 하는 것이 목적이다.
 * 매핑에 없는 옛한글 자모는 `null` — 기존대로 통과 문자로 취급된다.
 */
function conjoiningToCompat(code: number): string | null {
    if (code >= 0x1100 && code <= 0x1112) return LEADS[code - 0x1100];
    if (code >= 0x1161 && code <= 0x1175) return MEDIALS[code - 0x1161];
    if (code >= 0x11a8 && code <= 0x11c2) return FINALS[code - 0x11a8 + 1];
    return null;
}

/** 완성형 음절, 호환 자모, conjoining jamo를 구성 자모 문자열로 푼다. 겹모음·겹받침도 분해한다. */
function decomposeHangul(ch: string): string {
    const code = ch.charCodeAt(0);
    let jamos: string;
    if (code >= SYLLABLE_BASE && code <= SYLLABLE_LAST) {
        const offset = code - SYLLABLE_BASE;
        const finalIndex = offset % FINAL_COUNT;
        jamos =
            LEADS[Math.floor(offset / (MEDIAL_COUNT * FINAL_COUNT))] +
            MEDIALS[Math.floor(offset / FINAL_COUNT) % MEDIAL_COUNT] +
            (finalIndex === 0 ? "" : FINALS[finalIndex]);
    } else {
        jamos = conjoiningToCompat(code) ?? ch;
    }

    let out = "";
    for (const jamo of jamos) {
        out += CLUSTER_SPLIT[jamo] ?? jamo;
    }
    return out;
}

const isHangul = (ch: string): boolean => {
    const code = ch.charCodeAt(0);
    // 완성형 음절 / 호환 자모(U+3131-U+3163) / conjoining jamo(NFD)
    return (
        (code >= SYLLABLE_BASE && code <= SYLLABLE_LAST) ||
        (code >= 0x3131 && code <= 0x3163) ||
        conjoiningToCompat(code) !== null
    );
};

/**
 * CapsLock 상태를 모를 때 케이스 패턴에서 추론한다.
 *
 * CapsLock은 전역 모드이므로 가설은 둘뿐이다 — H1(꺼짐: 보이는 대문자 = 실제 shift) /
 * H2(켜짐: 케이스가 전부 반전됨). 그리고 두벌식에서 **shift를 누를 이유가 있는 키는
 * `qwertop` 7개뿐**이라는 데서 각 가설의 반박 조건이 나온다:
 *
 * - `qwertop` 밖의 대문자가 있다 → 누를 이유가 없는 자리에 shift가 들어갔다 → H1 반박
 * - `qwertop` 밖의 소문자가 있다 → CapsLock이 켜졌는데 그 자리에 shift가 들어갔다 → H2 반박
 *
 * 따라서 `gksrmf`·`Ekfrl`은 H2가 반박되어 확정, `GKSRMF`는 H1이 반박되어 확정이다.
 * **둘 다 살아남는 건 쿼리가 `qwertop` 글자로만 이루어진 경우뿐**(`e`, `we`, `to`) —
 * 사실상 1~2글자다. 그 구간은 어차피 후보가 넘쳐 정확도가 무의미하므로 H1으로 둔다.
 *
 * @returns CapsLock이 켜져 있었다고 판단하면 `true`
 */
function inferCapsLock(input: string): boolean {
    let h1Refuted = false;
    let h2Refuted = false;
    for (let i = 0; i < input.length; i++) {
        // ASCII 영문자만 증거로 삼는다 — 두벌식 키에 대응하지 않는 문자(그리스·키릴 대문자,
        // toUpperCase 가 길이를 바꾸는 ß 등)의 케이스는 shift 여부를 말해주지 않는다.
        const code = input.charCodeAt(i);
        const isUpper = code >= 0x41 && code <= 0x5a;
        const isLower = code >= 0x61 && code <= 0x7a;
        if (!isUpper && !isLower) continue;
        if (SHIFTABLE_KEYS.has(isUpper ? String.fromCharCode(code + 32) : input[i])) continue;
        if (isLower) h2Refuted = true;
        else h1Refuted = true;
    }
    return h1Refuted && !h2Refuted;
}

/**
 * 한/영 자판을 반대로 해석한 문자열을 만든다.
 *
 * 라틴 문자 구간은 두벌식 자모로 바꿔 IME와 동일하게 조합하고, 한글 구간은 자모로 풀어
 * QWERTY 키로 되돌린다. 그 밖의 문자(공백·숫자·기호)는 그대로 통과한다. 구간별로
 * 독립 처리하므로 `"제목 gksrmf"` 같은 혼합 입력도 각 구간이 제 방향으로 뒤집힌다.
 *
 * ```ts
 * swapLayout("gksrmf");        // "한글"
 * swapLayout("ㅗ디ㅣㅐ");        // "hello"
 * swapLayout("Ekfrl");         // "딸기"  (E = shift+e → ㄸ)
 * swapLayout("EKFRL", true);   // "달기"  (CapsLock 켜짐 → 케이스 반전 → ㄷ)
 * ```
 *
 * 되돌릴 게 없으면 입력을 그대로 반환하므로, 소비자는 `swapLayout(q) !== q`로
 * 시도할 가치가 있는지 판단할 수 있다. NFD로 분해된 한글(conjoining jamo)도 인식한다.
 *
 * **혼합 스크립트는 복원 대상이 아니다.** 이 함수는 기계적으로 모든 구간을 뒤집으므로
 * `"제목 gksrmf"` → `"wpahr 한글"`처럼 이미 올바른 부분까지 망가진다. 한영키를 깜빡하면
 * 쿼리 **전체**가 잘못되므로 실사용에서는 문제되지 않지만, 소비자는 한글과 라틴이 함께
 * 들어있는 입력에 대해서는 이 함수를 적용하지 않는 편이 낫다. 토큰마다 어느 해석이 맞는지
 * 고르려면 두 해석을 하나로 합치는 랭킹 레이어가 필요한데, 그건 라이브러리 밖이다
 * (design_notes.md Case 2).
 *
 * @param input 원본 입력. **case folding 전의 원문**이어야 한다 — shift 정보가 필요하다
 * @param capsLock CapsLock 상태를 안다면 전달한다 (브라우저에서는 keydown 이벤트의
 *   `getModifierState("CapsLock")`으로 읽을 수 있다). 생략하면 케이스 패턴에서 추론한다
 */
export function swapLayout(input: string, capsLock?: boolean): string {
    if (input === "") return "";

    const invertCase = capsLock ?? inferCapsLock(input);

    let out = "";
    let latinRun: string[] = []; // 조합 대기 중인 자모
    let hangulRun = "";

    const flushLatin = (): void => {
        if (latinRun.length > 0) {
            out += composeJamos(latinRun);
            latinRun = [];
        }
    };
    const flushHangul = (): void => {
        if (hangulRun !== "") {
            for (const jamo of hangulRun) {
                out += JAMO_TO_KEY[jamo] ?? jamo;
            }
            hangulRun = "";
        }
    };

    for (const ch of input) {
        const keyed = invertCase ? (ch === ch.toLowerCase() ? ch.toUpperCase() : ch.toLowerCase()) : ch;
        // shift가 다른 자모를 내지 않는 키(G, K, …)는 소문자와 같은 자모로 떨어진다.
        const jamo = KEY_TO_JAMO[keyed] ?? KEY_TO_JAMO[keyed.toLowerCase()];
        if (jamo !== undefined) {
            flushHangul();
            latinRun.push(jamo);
        } else if (isHangul(ch)) {
            flushLatin();
            hangulRun += decomposeHangul(ch);
        } else {
            flushLatin();
            flushHangul();
            out += ch;
        }
    }
    flushLatin();
    flushHangul();
    return out;
}
